      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 16px;
    }

    .form-field {
      padding: 20px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      padding: 0;
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 10px;
    }

    .help-text {
      margin: -2px 0 14px;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .choices {
      display: grid;
      gap: 10px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      background: var(--surface-alt);
      border: 1px solid transparent;
      border-radius: 14px;
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: #cbd5e1;
      background: #ffffff;
      transform: translateY(-1px);
    }

    .choice input {
      margin-top: 2px;
      width: 18px;
      height: 18px;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    .choice span {
      line-height: 1.45;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 4px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(180deg, var(--primary), var(--primary-strong));
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 28px rgba(37, 99, 235, 0.28);
    }

    button:focus-visible,
    .choice input:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .result {
      display: none;
      padding: 16px 18px;
      border-radius: 16px;
      background: #eff6ff;
      color: #1e3a8a;
      border: 1px solid #bfdbfe;
      line-height: 1.55;
    }

    .result[aria-hidden="false"] {
      display: block;
    }
  </style>
</head>
