    <form id="quiz-form" novalidate>
      <div class="form-field">
        <fieldset>
          <legend>1. Which of these are programming languages?</legend>
          <p class="help-text">Select every option that is a language used to write software.</p>
          <div class="choices">
            <label class="choice"><input type="checkbox" name="q1" value="JavaScript"><span>JavaScript</span></label>
            <label class="choice"><input type="checkbox" name="q1" value="HTML"><span>HTML</span></label>
            <label class="choice"><input type="checkbox" name="q1" value="Python"><span>Python</span></label>
            <label class="choice"><input type="checkbox" name="q1" value="CSS"><span>CSS</span></label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>2. Which languages are commonly used for backend development?</legend>
          <div class="choices">
            <label class="choice"><input type="checkbox" name="q2" value="Ruby"><span>Ruby</span></label>
            <label class="choice"><input type="checkbox" name="q2" value="JavaScript"><span>JavaScript</span></label>
            <label class="choice"><input type="checkbox" name="q2" value="COBOL"><span>COBOL</span></label>
            <label class="choice"><input type="checkbox" name="q2" value="Swift"><span>Swift</span></label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>3. Which of these are considered low-level languages?</legend>
          <div class="choices">
            <label class="choice"><input type="checkbox" name="q3" value="Assembly"><span>Assembly</span></label>
            <label class="choice"><input type="checkbox" name="q3" value="Machine code"><span>Machine code</span></label>
            <label class="choice"><input type="checkbox" name="q3" value="TypeScript"><span>TypeScript</span></label>
            <label class="choice"><input type="checkbox" name="q3" value="Python"><span>Python</span></label>
          </div>
        </fieldset>
      </div>

      <div class="actions">
        <button type="submit">Submit quiz</button>
      </div>

      <div class="result" id="result" aria-live="polite" aria-hidden="true"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const questions = [
        { key: 'q1', label: 'Question 1' },
        { key: 'q2', label: 'Question 2' },
        { key: 'q3', label: 'Question 3' }
      ];

      const summary = questions.map(({ key, label }) => {
        const selected = Array.from(form.querySelectorAll(`input[name="${key}"]:checked`)).map((input) => input.value);
        return `${label}: ${selected.length ? selected.join(', ') : 'No answers selected'}`;
      });

      result.textContent = `Your selections — ${summary.join(' | ')}`;
      result.setAttribute('aria-hidden', 'false');
    });
  </script>
</body>
</html>
